  };

  return (
    <Modal
      isOpen={isModalOpen}
      onClose={() => {
        if (currentStep === 4) {
          setCurrentStep(3);
        } else {
          setIsModalOpen(false);
        }
      }}
      showCloseButton={true}
      closeOnBackdropClick={false}
    >
      <div className="w-full min-h-[480px] sm:h-[650px] flex flex-col justify-between items-center px-2 sm:px-0">
        {currentStep !== 4 && (
          <Image
